import json

def get_extracted_fields(prompt, client):
    response = client.chat.completions.create(
        model="gpt-4.1",
        messages=[{"role": "user", "content": prompt + "\n\nReturn the result as JSON."}],   # JSON mode requires the word JSON in the messages
        response_format={"type": "json_object"},   # asks the API to guarantee valid JSON syntax
    )
    raw = response.choices[0].message.content.strip()
    if raw.startswith("```"):
        raw = raw.strip("`").removeprefix("json").strip()
    try:
        return json.loads(raw)
    except json.JSONDecodeError as e:
        raise ValueError(f"Model returned unparseable content: {raw!r}") from e

